/*
 * Terminal profiles for the Kitty video driver. Two TOML files:
 *
 *  - terminals.toml: facts about terminals, shared with other programs
 *    (https://github.com/visionik/terminal-facts, schema 1). How to recognise
 *    each terminal (XTVERSION first), and what it really does.
 *  - sdl-kitty.toml: this driver's own tuning, keyed by the same row ids.
 *
 * Both are compiled in (SDL_kittyprofile_data.h, generated by sdl-kitty's
 * scripts/update_facts.py); files found at run time replace the facts or
 * overlay the tuning. Facts win over tuning where they decide a setting, and
 * SDL_KITTY_* environment variables win over both. See sdl-kitty's
 * docs/terminal-profiles.md.
 */
#ifdef KITTY_PROFILE_STANDALONE
#include <SDL3/SDL.h>
#else
#include "SDL_internal.h"
#endif

#ifndef SDL_kittyprofile_h_
#define SDL_kittyprofile_h_

#if defined(SDL_VIDEO_DRIVER_KITTY) || defined(KITTY_PROFILE_STANDALONE)

#include <stddef.h>

typedef enum KITTY_TerminalKind
{
    KITTY_TERM_UNKNOWN = 0,
    KITTY_TERM_REX,
    KITTY_TERM_KITTY,
    KITTY_TERM_GHOSTTY,
    KITTY_TERM_WEZTERM
} KITTY_TerminalKind;

/* A fact from terminals.toml that's a yes/no: unknown unless the file says. */
typedef enum KITTY_Fact
{
    KITTY_FACT_UNKNOWN = -1,
    KITTY_FACT_NO = 0,
    KITTY_FACT_YES = 1
} KITTY_Fact;

/*
 * The facts for the recognised terminal, with every matching row applied
 * (terminal-facts SPEC.md). A missing fact is unknown: probe, or use tuning.
 */
typedef struct KITTY_TerminalFacts
{
    KITTY_Fact placeholders;      /* kitty.placeholders */
    KITTY_Fact frame_edit;        /* kitty.frame_edit: a=f shows on screen */
    KITTY_Fact frame_edit_reply;  /* kitty.frame_edit_reply: answers a=f */
    KITTY_Fact frame_edit_zlib;   /* kitty.frame_edit_zlib: a=f with o=z shows */
    KITTY_Fact animation;         /* kitty.animation */
    KITTY_Fact shm;               /* kitty.shm: t=s works */
    size_t max_escape_bytes;      /* kitty.max_escape_bytes; 0 = unknown */
    size_t storage_bytes;         /* kitty.storage_bytes; 0 = unknown */
    char fastest_format[8];       /* kitty.fastest_format; "" = unknown */
    KITTY_Fact iterm2_gif_animation; /* iterm2.gif_animation */
    KITTY_Fact ioctl_pixels;      /* window.ioctl_pixels */
    char keyboard_config[192];    /* keyboard.kitty_protocol_config; "" = unknown */
} KITTY_TerminalFacts;

/*
 * Facts and tuning for the terminal we're in. Runtime probes (a=q / SHM / a=f)
 * still decide what is *available*; this struct decides defaults and quirk
 * thresholds.
 */
typedef struct KITTY_TerminalProfile
{
    KITTY_TerminalKind kind;
    /* The recognised terminal's id in terminals.toml ("ghostty", also for
     * Ghostty 1.3.1), or "unknown". */
    const char *name;
    /* Every row applied, comma-separated ("ghostty,ghostty-1.3"). */
    const char *rows;
    /* As the terminal reported it; "" when unknown. */
    const char *version;
    /* "xtversion", "env", "term_program", "term", or "" when unknown. */
    const char *recognised_by;
    KITTY_TerminalFacts facts;

    /* When both SHM and direct probe OK, prefer direct (Rex). */
    bool prefer_direct;

    /*
     * When not using SHM, prefer zlib-compressed direct (o=z) over raw base64.
     * Env SDL_KITTY_TRANSMIT still wins. Exp 2 soak: wezterm true.
     */
    bool prefer_zlib;

    /*
     * Optional profile force of transmit medium: "direct", "zlib", "shm", or NULL.
     * Applied after env. Ghostty zlib A/B without changing prefer_direct/SHM default.
     */
    const char *force_transmit;

    /* Default aspect-fit FB cap when SDL_KITTY_FB_MAX unset. 0 = no default cap. */
    int default_fb_max_w;
    int default_fb_max_h;

    /*
     * Transport-aware soft-maxes (source-backed; see config/terminals.toml notes).
     * 0 = fall back to default_fb_max_*. Applied from KITTY_ApplyFramebufferCap
     * using transmit_mode after probe (SHM vs direct/zlib).
     */
    int default_fb_max_shm_w;
    int default_fb_max_shm_h;
    int default_fb_max_direct_w;
    int default_fb_max_direct_h;

    /* Refuse direct a=T / fallback above this many raw bytes. */
    size_t max_direct_bytes;

    /* Skip a=f (use full a=T) when dirty coverage or pixel count exceeds. */
    float af_max_coverage;
    size_t af_max_pixels;

    /* Compress a=f edits (o=z). From kitty.frame_edit_zlib when that's known;
     * else tuning (off). SDL_KITTY_AF_ZLIB=0/1 wins. */
    bool af_zlib;

    /* Read keyboard from stdin (Rex delivers keys on fd0 only). */
    bool keys_on_stdin;

    /* Treat silent a=f probe as success. From kitty.frame_edit_reply when
     * that's known (Rex: false, so silence is success); else tuning. */
    bool silent_af_ok;

    /* Skip the a=f probe: kitty.frame_edit = false (WezTerm, Ghostty 1.3.1). */
    bool skip_af_probe;

    /* --- §B host conditionals (Phase 4 wires call sites) --- */

    /* Ignore TIOCGWINSZ xpixel/ypixel: window.ioctl_pixels = false (Rex);
     * else tuning. */
    bool ignore_ioctl_pixels;

    /* Allow direct a=f while transmit_mode is SHM (Rex true; Kitty false). */
    bool direct_af_when_shm;

    /*
     * Experiment: sparse dirty updates as stacked a=T overlays (one image per
     * dirty rect) when a=f cannot refresh the display (WezTerm hash bug).
     * Env SDL_KITTY_DIRTY_AT=0|1 overrides. Default off (host hang).
     */
    bool dirty_at_overlays;

    /*
     * Exp 3: single union a=T overlay (DECSC/DECRC + edge skip). Safer than
     * multi dirty_at. Env SDL_KITTY_DIRTY_UNION_AT=0|1 overrides.
     */
    bool dirty_union_at;

    /*
     * Exp 6: skip wire upload when full scratch FNV matches last successful
     * upload (no-op present). Env SDL_KITTY_UPLOAD_SKIP=0|1 overrides.
     */
    bool upload_skip;

    /*
     * Exp 5: merge dirty rects whose expanded boxes intersect (gap in pixels).
     * 0 = off. Env SDL_KITTY_COALESCE_GAP overrides.
     */
    int coalesce_gap_px;

    /* Max raw size for SHM-fail → direct fallback when !prefer_direct. */
    size_t direct_fallback_max_bytes;

    /* --- §C tunables (usually from [defaults]; Phase 4 wires call sites) --- */

    size_t apc_chunk_bytes;
    int probe_timeout_ms;
    int drain_passes;
    int drain_quiet_us;
    int stub_winch_iters;
    int stub_winch_delay_ms;
    int stub_cols;
    int stub_rows;
    int key_hold_ms;
    bool fb_diff;
    int fb_diff_tile;
    float fb_diff_cover;
    int tty_pending_max;
    int window_fallback_w;
    int window_fallback_h;
    bool place_cells;
    bool pingpong;
    /* Protocol: terminal unlinks after read — client must not unlink on success. */
    bool shm_unlink_after_send;

    /* Docs / DEBUG only; may be NULL. */
    const char *notes;
} KITTY_TerminalProfile;

/*
 * Load the compiled-in facts and tuning, then files found at run time:
 * facts from SDL_KITTY_FACTS (else terminals.toml in the pref or base path,
 * else KITTY_DEFAULT_FACTS_PATH), tuning from SDL_KITTY_PROFILES (a
 * colon-separated list; else sdl-kitty.toml in the pref or base path, else
 * KITTY_DEFAULT_PROFILES_PATH). Idempotent until Reset.
 */
void KITTY_EnsureTerminalProfilesLoaded(void);

/*
 * Replace the facts with a terminals.toml file. A file that doesn't follow
 * schema 1 is refused, keeping the facts already loaded. Returns success.
 */
bool KITTY_LoadTerminalFacts(const char *path);

/*
 * Overlay tuning from an sdl-kitty.toml file onto what's loaded. Returns
 * success.
 */
bool KITTY_LoadTerminalProfiles(const char *path);

/*
 * Back to the compiled-in files only; the next Ensure/Detect searches again.
 */
void KITTY_ResetTerminalProfilesToBuiltin(void);

/*
 * The profile for the terminal recognised from the environment alone.
 * Never returns NULL. The result is shared: a later Detect call replaces it.
 */
const KITTY_TerminalProfile *KITTY_DetectTerminalProfile(void);

/*
 * The profile for the terminal recognised from its XTVERSION answer (the
 * text inside DCS > | ... ST, e.g. "ghostty 1.3.1"), falling back to the
 * environment when xtversion is NULL or names no row. os_name is "macos",
 * "linux", "windows" or "bsd"; NULL means this system. Never returns NULL.
 */
const KITTY_TerminalProfile *KITTY_IdentifyTerminalProfile(const char *xtversion,
                                                           const char *os_name);

/*
 * The files loaded, for DEBUG: "builtin", or "builtin;<path>;..." Never NULL.
 */
const char *KITTY_TerminalProfilesSource(void);

/*
 * True when the environment names a terminal in terminals.toml (used by
 * ProbeSupport). Ensures profiles are loaded first.
 */
bool KITTY_EnvMatchesLoadedProfile(void);

/*
 * APC payload chunk size from profile (derived from kitty.max_escape_bytes
 * when that's known), or 2 MiB when unset/zero.
 */
static inline size_t KITTY_ProfileApcChunkBytes(const KITTY_TerminalProfile *p)
{
    return (p && p->apc_chunk_bytes > 0) ? p->apc_chunk_bytes : ((size_t)2 * 1024 * 1024);
}

/*
 * Max raw bytes for SHM-fail → direct fallback, or 256 KiB when unset/zero.
 */
static inline size_t KITTY_ProfileDirectFallbackBytes(const KITTY_TerminalProfile *p)
{
    return (p && p->direct_fallback_max_bytes > 0) ? p->direct_fallback_max_bytes
                                                   : ((size_t)256 * 1024);
}

/*
 * Probe wait budget (attempts) from profile probe_timeout_ms, or 40.
 */
static inline int KITTY_ProfileProbeAttempts(const KITTY_TerminalProfile *p)
{
    return (p && p->probe_timeout_ms > 0) ? p->probe_timeout_ms : 40;
}

#endif /* SDL_VIDEO_DRIVER_KITTY || KITTY_PROFILE_STANDALONE */
#endif /* SDL_kittyprofile_h_ */
